<?php//-------------------------------------------------------------------// class GeoIPManager//-------------------------------------------------------------------class GeoIPManager{    //---------------------------------------------------------------    function analyze_ip($ip, $bot, $dtnow)    {        global $settings;        global $READ_MARKER;        $dbw = System::getDBWorker();        if (!$dbw) {            return false;        }        $prfx = $dbw->escape(System::getDBPrefix());        if (!defined("GETGEOAPI_API_KEYS") || empty(GETGEOAPI_API_KEYS)) {            return false;        }        if (!empty($settings["hash_ip_addresses"])) {            return false;        }        if (empty($ip)) {            return false;        }        $api_key = GETGEOAPI_API_KEYS[array_rand(GETGEOAPI_API_KEYS)];        $language = "en";        if (defined("GETGEOAPI_API_LANGUAGE") && !empty(GETGEOAPI_API_LANGUAGE)) {            $language = GETGEOAPI_API_LANGUAGE;        }        try {            $url = "https://api.getgeoapi.com/v2/ip/" . $ip . "?api_key=" . $api_key . "&format=json&language=" . $language;            $client = new Zend_Http_Client($url, array(                'maxredirects' => 5,                'timeout' => 50            ));            $request = $client->request('GET');            $response = $request->getBody();            $json = json_decode($response, true);            if (!$json) {                return true;            }            if (val_or_empty($json["status"]) != "success") {                if (!empty($json["error"]["message"])) {                    throw new Exception("GeoIP Error: " . $json["error"]["message"]);                }                return false;            }            $ip_db = $dbw->escape($ip);            $country_code = val_or_empty($json["country"]["code"]);            $country = val_or_empty($json["country"]["name"]);            $city = val_or_empty($json["city"]["name"]);            $is_tor = empty($json["security"]["is_tor"]) ? 0 : 1;            $is_proxy = empty($json["security"]["is_proxy"]) ? 0 : 1;            $is_ipv6 = val_or_empty($json["type"]) == "IPv6" ? 1 : 0;            $dtnow_db = $dbw->format_date($dtnow);            $country_code = $dbw->quotes_or_null($country_code);            $country = $dbw->quotes_or_null($country);            $city = $dbw->quotes_or_null($city);            $bot_db = $dbw->quotes_or_null($bot);            $rm = $dbw->escape($READ_MARKER);            if ($bot_db != "NULL") {                $query = "update {$prfx}_ip_daily_statistics set                                          country_code = $country_code,                                           country = $country,                                           city = $city,                                          is_tor = $is_tor,                                           is_proxy = $is_proxy,                                           is_ipv6 = $is_ipv6                                          where ip = '$ip_db' and bot = $bot_db and dt = $dtnow_db";            } else {                $query = "update {$prfx}_ip_daily_statistics set                                          country_code = $country_code,                                           country = $country,                                           city = $city,                                          is_tor = $is_tor,                                           is_proxy = $is_proxy,                                           is_ipv6 = $is_ipv6                                          where ip = '$ip_db' and read_marker = '$rm' and bot is NULL and dt = $dtnow_db";            }            if (!$dbw->execute_query($query)) {                MessageHandler::setError(text("ErrQueryFailed"), $dbw->get_last_error() . "\n\n" . $dbw->get_last_query());                return false;            }        } catch (Exception $ex) {            //trigger_error($ex->getMessage(), E_USER_WARNING);            // If GEO API fails not problem            return true;        }        return true;    } // analyze_ip    //---------------------------------------------------------------    function check_ip($dbw, $ip, $bot)    {        global $settings;        global $READ_MARKER;                if (!defined("GETGEOAPI_API_KEYS") || empty(GETGEOAPI_API_KEYS)) {            return false;        }        if (!empty($settings["hash_ip_addresses"])) {            return false;        }        if (empty($ip)) {            return false;        }        $prfx = $dbw->escape(System::getDBPrefix());                $ip_db = $dbw->escape($ip);        if (!$dbw->execute_query("select country_code, country, city, is_tor, is_proxy, is_ipv6                                   from {$prfx}_ip_daily_statistics                                  where                                  ip = '$ip_db'                                 ")) {            MessageHandler::setError(text("ErrQueryFailed"), $dbw->get_last_error() . "\n\n" . $dbw->get_last_query());                        return false;        }                $country_code = "";         $country = "";         $city = "";         $is_tor = 0;         $is_proxy = 0;         $is_ipv6 = 0;                $exists = false;        if ($dbw->fetch_row()) {            $exists = true;                        $country_code = $dbw->field_by_name("country_code");            $country = $dbw->field_by_name("country");            $city = $dbw->field_by_name("city");            $is_tor = $dbw->field_by_name("is_tor");            $is_proxy = $dbw->field_by_name("is_proxy");            $is_ipv6 = $dbw->field_by_name("is_ipv6");        }                $dbw->free_result();        $dtnow = mktime(0, 0, 0, date("n"), date("j"), date("Y"));        $dtnow_db = $dbw->format_date($dtnow);        $country_code = $dbw->quotes_or_null($country_code);        $country = $dbw->quotes_or_null($country);        $city = $dbw->quotes_or_null($city);        $bot_db = $dbw->quotes_or_null($bot);        $rm = $dbw->escape($READ_MARKER);                if ($bot_db != "NULL") {            if (!$dbw->execute_query("insert into {$prfx}_ip_daily_statistics                                      (dt, ip, bot, country_code, country, city, is_tor, is_proxy, is_ipv6)                                      select                                      $dtnow_db, '$ip_db', $bot_db, $country_code, $country, $city, $is_tor, $is_proxy, $is_ipv6                                      from {$prfx}_dual                                      where                                      not exists (select 1 from {$prfx}_ip_daily_statistics where ip = '$ip_db' and bot = $bot_db and dt = $dtnow_db)                                     ")) {                MessageHandler::setError(text("ErrQueryFailed"), $dbw->get_last_error() . "\n\n" . $dbw->get_last_query());                                return false;            }            if (!$dbw->execute_query("update {$prfx}_ip_daily_statistics                                      set hits_count = hits_count + 1                                      where                                      ip = '$ip_db' and bot = $bot_db and dt = $dtnow_db                                     ")) {                MessageHandler::setError(text("ErrQueryFailed"), $dbw->get_last_error() . "\n\n" . $dbw->get_last_query());                                return false;            }        } else {            if (!$dbw->execute_query("insert into {$prfx}_ip_daily_statistics                                      (dt, ip, country_code, country, city, is_tor, is_proxy, is_ipv6, read_marker)                                      select                                      $dtnow_db, '$ip_db', $country_code, $country, $city, $is_tor, $is_proxy, $is_ipv6, '$rm'                                      from {$prfx}_dual                                      where                                      not exists (select 1 from {$prfx}_ip_daily_statistics where ip = '$ip_db' and read_marker = '$rm' and bot is NULL and dt = $dtnow_db)                                     ")) {                MessageHandler::setError(text("ErrQueryFailed"), $dbw->get_last_error() . "\n\n" . $dbw->get_last_query());                                return false;            }                        if (!$dbw->execute_query("update {$prfx}_ip_daily_statistics                                      set hits_count = hits_count + 1                                      where                                      ip = '$ip_db' and read_marker = '$rm' and bot is NULL and dt = $dtnow_db                                     ")) {                MessageHandler::setError(text("ErrQueryFailed"), $dbw->get_last_error() . "\n\n" . $dbw->get_last_query());                                return false;            }        }        // zzzz        $exists = false;        if (!$exists) {            // trigger async request            // 1. Host            $host = val_or_empty($_SERVER["HTTP_HOST"]);            if (empty($host)) {                $host = val_or_empty($_SERVER["SERVER_NAME"]);            }            // 2. Scheme and port            $is_https = (!empty($_SERVER["HTTPS"]) && strtolower($_SERVER["HTTPS"]) != "off")                || val_or_empty($_SERVER["SERVER_PORT"]) == 443;            $port = (int)val_or_empty($_SERVER["SERVER_PORT"]);            if ($port < 1) {                $port = $is_https ? 443 : 80;            }            // 3. Connect to the address the request arrived on, NOT to $host            $connect_ip = val_or_empty($_SERVER["SERVER_ADDR"]);            if (empty($connect_ip) || !filter_var($connect_ip, FILTER_VALIDATE_IP)) {                $connect_ip = "127.0.0.1";            }            if (strpos($connect_ip, ":") !== false) { // IPv6 literal                $connect_ip = "[" . $connect_ip . "]";            }            $body = http_build_query(array(                "ip" => $ip,                "bot" => $bot,                "dtnow" => $dtnow,                "token" => hash_hmac("sha256", $ip, SALT_KEY)            ));            $hostname_only = preg_replace('/:\d+$/', '', $host);            $path = get_url_path() . "ajax/async_analyze_ip.php"; // see below            $ctx = stream_context_create(array("ssl" => array("peer_name" => $hostname_only)));            $errstr = false;            $fp = @stream_socket_client(                ($is_https ? "ssl://" : "tcp://") . $connect_ip . ":" . $port,                $errno, $errstr, 1, STREAM_CLIENT_CONNECT, $ctx            );            if (!$fp) {                // If GEO API fails not problem                return true;            }            $out  = "POST $path HTTP/1.1\r\n";            $out .= "Host: $host\r\n";            $out .= "Content-Type: application/x-www-form-urlencoded\r\n";            $out .= "Content-Length: " . strlen($body) . "\r\n";            $out .= "Connection: Close\r\n\r\n";            $out .= $body;            fwrite($fp, $out);            fclose($fp);        }        return true;    } // check_ip    //---------------------------------------------------------------} // GeoIPManager//-------------------------------------------------------------------?>